74	 */
75	
76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /**
85	     * Source of the {@link OwnerCreatedEvent}'s {@code seq}: a process-wide, monotonically increasing counter across
86	     * every owner create, so the structured audit events carry a strictly ordered sequence regardless of which
87	     * controller instance handled the request.
88	     */
89	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
90	
91	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
92	    private static final int MAX_OWNERS_PER_CITY = 50;
93	
94	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
98	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
99	
100	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
101	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
102	
103	    /**
104	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
105	     * create with an already-seen key returns the original owner instead of creating a duplicate.
106	     */
107	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
108	
109	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
110	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
111	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
112	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
113	
114	    private final ClinicService clinicService;
115	
116	    private final OwnerMapper ownerMapper;
117	
118	    private final PetMapper petMapper;
119	
120	    private final VisitMapper visitMapper;
121	
122	    private final TelephoneNormalizer telephoneNormalizer;
123	
124	    private final AddressNormalizer addressNormalizer;
125	
126	    private final EmailNormalizer emailNormalizer;
127	
128	    private final IdentityKeyResolver identityKeyResolver;
129	
130	    private final HouseholdResolver householdResolver;
131	
132	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
133	    private final HttpServletRequest request;
134	
135	    public OwnerRestControllerV1(ClinicService clinicService,
136	                                 OwnerMapper ownerMapper,
137	                                 PetMapper petMapper,
138	                                 VisitMapper visitMapper,
139	                                 TelephoneNormalizer telephoneNormalizer,
140	                                 AddressNormalizer addressNormalizer,
141	                                 EmailNormalizer emailNormalizer,
142	                                 IdentityKeyResolver identityKeyResolver,
143	                                 HouseholdResolver householdResolver,
144	                                 HttpServletRequest request) {
145	        this.clinicService = clinicService;
146	        this.ownerMapper = ownerMapper;
147	        this.petMapper = petMapper;
148	        this.visitMapper = visitMapper;
149	        this.telephoneNormalizer = telephoneNormalizer;
150	        this.addressNormalizer = addressNormalizer;
151	        this.emailNormalizer = emailNormalizer;
152	        this.identityKeyResolver = identityKeyResolver;
153	        this.householdResolver = householdResolver;
154	        this.request = request;
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
160	        Collection<Owner> owners;
161	        if (lastName != null) {
162	            owners = this.clinicService.findOwnerByLastName(lastName);
163	        } else {
164	            owners = this.clinicService.findAllOwners();
165	        }
166	        if (owners.isEmpty()) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        owners.forEach(this::populateHouseholdMemberCount);
170	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
171	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        populateHouseholdMemberCount(owner);
182	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
183	    }
184	
185	    /**
186	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
187	     * it depends on more than the single owner: the {@code identityKey} (see
188	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
189	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
190	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
191	     * mapper's uncapped one on the returned DTO.
192	     *
193	     * @param owner the owner to map
194	     * @return the owner DTO carrying its identity key and household-capped membership level
195	     */
196	    private OwnerDto toOwnerDto(Owner owner) {
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
199	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
200	        return ownerDto;
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Transactional
205	    @Override
206	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
207	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
208	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
209	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
210	            if (replay != null) {
211	                return replay;
212	            }
213	        }
214	        Owner owner = createOwner(ownerFieldsDto);
215	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
216	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
217	        }
218	        return createdOwnerResponse(owner);
219	    }
220	
221	    /**
222	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
223	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
224	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
225	     * normally.
226	     *
227	     * @param idempotencyKey the client-supplied idempotency key from the request header
228	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
229	     */
230	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
231	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
232	        if (existingId == null) {
233	            return null;
234	        }
235	        Owner owner = this.clinicService.findOwnerById(existingId);
236	        if (owner == null) {
237	            return null;
238	        }
239	        populateHouseholdMemberCount(owner);
240	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
241	    }
242	
243	    /**
244	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
245	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
246	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
247	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
248	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
249	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
250	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
251	     *
252	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
253	     * @return the newly created, persisted owner
254	     */
255	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
256	        normalizeAndValidate(ownerFieldsDto);
257	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
258	        populateDerivedFields(owner, ownerFieldsDto);
259	        requireUniqueIdentity(owner);
260	        flagPossibleDuplicate(owner, ownerFieldsDto);
261	        this.clinicService.saveOwner(owner);
262	        populateHouseholdMemberCount(owner);
263	        auditOwnerCreated(owner);
264	        return owner;
265	    }
266	
267	    /**
268	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
269	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
270	     * canonical URL.
271	     *
272	     * @param owner the newly created, persisted owner
273	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
274	     */
275	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
276	        OwnerDto ownerDto = toOwnerDto(owner);
277	        HttpHeaders headers = new HttpHeaders();
278	        headers.setLocation(UriComponentsBuilder.newInstance()
279	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
280	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
281	    }
282	
283	    /**
284	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
285	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
286	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
287	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
288	     * {@link FiscalYearResolver#fiscalYear}).
289	     *
290	     * <p>In addition to the human-readable line, a single immutable structured event is emitted as JSON (see
291	     * {@link OwnerCreatedEvent}), carrying a monotonically increasing {@code seq} (see
292	     * {@link #OWNER_CREATED_SEQUENCE}), the owner's id, its current primary identifier (see
293	     * {@link #primaryIdentifier(Owner)}) and its membership level under the {@code OWNER_CREATED} event type.
294	     *
295	     * @param owner the newly created, persisted owner, with all its derived fields already in place
296	     */
297	    private void auditOwnerCreated(Owner owner) {
298	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
299	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
300	            MembershipLevelResolver.deriveMembershipLevel(owner),
301	            owner.getCustomerCode() + "-M" + String.format("%02d",
302	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
303	        OwnerCreatedEvent event = new OwnerCreatedEvent(OWNER_CREATED_SEQUENCE.incrementAndGet(),
304	            owner.getId(), primaryIdentifier(owner), cappedMembershipLevel(owner));
305	        AUDIT.info(event.toJson());
306	    }
307	
308	    /**
309	     * Returns the owner's current primary identifier — the value the structured {@link OwnerCreatedEvent} carries as the
310	     * owner's identity. Today that is the {@code customerCode}; when the customer code is later unified into a
311	     * {@code memberId}, this single method changes to return the member id and the event carries it instead, with no
312	     * other change to the emission.
313	     *
314	     * @param owner the newly created, persisted owner
315	     * @return the owner's current primary identifier
316	     */
317	    private String primaryIdentifier(Owner owner) {
318	        return owner.getCustomerCode();
319	    }
320	
321	    /**
322	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
323	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
324	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
325	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
326	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
327	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
328	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
329	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
330	     *
331	     * @param owner          the newly mapped owner about to be saved
332	     * @param ownerFieldsDto the incoming owner payload
333	     */
334	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
335	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
336	        owner.setNamesakeCount(countNamesakes(owner));
337	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
338	        assignHouseholdId(owner);
339	    }
340	
341	    /**
342	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
343	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
344	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
345	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
346	     * that predate this create; distinct owners therefore always receive distinct customer codes.
347	     *
348	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
349	     * @return the de-duplicated customer code, unique across all existing owners
350	     */
351	    private String deriveUniqueCustomerCode(Owner owner) {
352	        String base = identityKeyResolver.deriveCustomerCode(owner);
353	        Collection<Owner> existing = this.clinicService.findAllOwners();
354	        String candidate = base;
355	        int n = 2;
356	        while (isCustomerCodeInUse(candidate, existing)) {
357	            candidate = base + "-" + n;
358	            n++;
359	        }
360	        return candidate;
361	    }
362	
363	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
364	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
365	    }
366	
367	    /**
368	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
369	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
370	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
371	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
372	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
373	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
374	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
375	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
376	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
377	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
378	     * assigned (see {@link #requireUniqueIdentity}).
379	     *
380	     * @param ownerFieldsDto the incoming owner payload, mutated in place
381	     * @throws MissingOwnerFieldsException if any required field is missing or blank
382	     */
383	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
384	        normalizeAddress(ownerFieldsDto);
385	        validateRequiredFields(ownerFieldsDto);
386	        validatePostcode(ownerFieldsDto);
387	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
388	        ownerFieldsDto.setTelephone(telephone);
389	        requireCityHasCapacity(ownerFieldsDto.getCity());
390	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
391	        ownerFieldsDto.setRegistrationDate(registrationDate);
392	        requireDailyLimitNotReached(registrationDate);
393	        normalizeEmail(ownerFieldsDto);
394	    }
395	
396	    /**
397	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
398	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
399	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
400	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
401	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
402	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
403	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
404	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
405	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
406	     *
407	     * @param ownerFieldsDto the incoming owner payload, mutated in place
408	     */
409	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
410	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
411	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
412	        if (!line1.isEmpty()) {
413	            ownerFieldsDto.setAddressLine1(line1);
414	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
415	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
416	        }
417	        else {
418	            ownerFieldsDto.setAddressLine1(null);
419	            ownerFieldsDto.setAddressLine2(null);
420	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
421	        }
422	    }
423	
424	    /**
425	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
426	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
427	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
428	     * place so the caller can map and save it directly.
429	     *
430	     * @param ownerFieldsDto the incoming owner payload, mutated in place
431	     */
432	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
433	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
434	    }
435	
436	    /**
437	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
438	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
439	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
440	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
441	     * date is rejected.
442	     *
443	     * @param ownerFieldsDto the incoming owner payload
444	     * @return the effective registration date rolled forward onto a business day
445	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
446	     */
447	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
448	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
449	        if (effective == null) {
450	            effective = LocalDate.now();
451	        }
452	        else if (effective.isAfter(LocalDate.now())) {
453	            throw new FutureRegistrationDateException(
454	                "the registration date must not be later than the current server date");
455	        }
456	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
457	            || PUBLIC_HOLIDAYS.contains(effective)) {
458	            effective = effective.plusDays(1);
459	        }
460	        return effective;
461	    }
462	
463	    /**
464	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
465	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
466	     * further owner may be created for that day.
467	     *
468	     * @param registrationDate the adjusted business-day registration date of the owner being created
469	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
470	     */
471	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
472	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
473	            throw new DailyOwnerLimitExceededException(
474	                "the maximum number of owners for today has already been reached");
475	        }
476	    }
477	
478	    /**
479	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
480	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
481	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
482	     * warning threshold) so both express the same per-day count in one place.
483	     *
484	     * @param registrationDate the adjusted business-day registration date to count owners for
485	     * @return the number of existing owners registered on that day
486	     */
487	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
488	        return this.clinicService.findAllOwners().stream()
489	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
490	            .count();
491	    }
492	
493	    /**
494	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
495	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
496	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
497	     * reflects only owners that predate it.
498	     *
499	     * @param registrationDate the adjusted business-day registration date of the owner being created
500	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
501	     */
502	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
503	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
504	    }
505	
506	    /**
507	     * Counts how many existing owners already share the given owner's first and last name, compared
508	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
509	     * create; it is zero when the owner's name is unique.
510	     *
511	     * @param owner the newly mapped owner about to be saved
512	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
513	     */
514	    private int countNamesakes(Owner owner) {
515	        String firstName = owner.getFirstName();
516	        String lastName = owner.getLastName();
517	        return (int) this.clinicService.findAllOwners().stream()
518	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
519	                && lastName.equalsIgnoreCase(existing.getLastName()))
520	            .count();
521	    }
522	
523	    /**
524	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
525	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
526	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
527	     *
528	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
529	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
530	     * flat {@code address}.
531	     *
532	     * @param ownerFieldsDto the owner payload to validate
533	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
534	     */
535	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
536	        List<String> missingFields = new ArrayList<>();
537	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
538	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
539	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
540	        requireText(missingFields, "city", ownerFieldsDto.getCity());
541	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
542	        if (!missingFields.isEmpty()) {
543	            throw new MissingOwnerFieldsException(missingFields);
544	        }
545	    }
546	
547	    private void requireText(List<String> missingFields, String fieldName, String value) {
548	        if (value == null || value.isBlank()) {
549	            missingFields.add(fieldName);
550	        }
551	    }
552	
553	    /**
554	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
555	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
556	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
557	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
558	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
559	     *
560	     * @param ownerFieldsDto the incoming owner payload
561	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
562	     */
563	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
564	        String postcode = ownerFieldsDto.getPostcode();
565	        if (postcode == null) {
566	            return;
567	        }
568	        Region region = Region.forCity(ownerFieldsDto.getCity());
569	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
570	            throw new InvalidPostcodeException(
571	                "postcode " + postcode + " is not valid for the city's region " + region.name());
572	        }
573	    }
574	
575	    /**
576	     * Rejects creating an owner whose whole derived {@code identityKey} (see
577	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
578	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
579	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
580	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
581	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
582	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
583	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
584	     * does not block the create.
585	     *
586	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
587	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
588	     */
589	    private void requireUniqueIdentity(Owner owner) {
590	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
591	        boolean inUse = this.clinicService.findAllOwners().stream()
592	            .filter(existing -> !existing.isDeleted())
593	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
594	        if (inUse) {
595	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
596	        }
597	    }
598	
599	    /**
600	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
601	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
602	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
603	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
604	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
605	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
606	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
607	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
608	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
609	     *
610	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
611	     * @param ownerFieldsDto the incoming owner payload
612	     */
613	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
614	        owner.setPossibleDuplicate(false);
615	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
616	            return;
617	        }
618	        String postcode = owner.getPostcode();
619	        if (postcode == null || postcode.isBlank()) {
620	            return;
621	        }
622	        for (Owner existing : this.clinicService.findAllOwners()) {
623	            if (isPossibleDuplicateOf(owner, existing)) {
624	                owner.setPossibleDuplicate(true);
625	                owner.setPossibleDuplicateOf(existing.getId());
626	                return;
627	            }
628	        }
629	    }
630	
631	    /**
632	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
633	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
634	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
635	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
636	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
637	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
638	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
639	     *
640	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
641	     * @param existing an already-persisted owner to test the new owner against
642	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
643	     */
644	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
645	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
646	            && owner.getPostcode().equals(existing.getPostcode())
647	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
648	    }
649	
650	    /**
651	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
652	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
653	     *
654	     * @param city the city of the owner being created
655	     * @throws OwnerCityFullException if the city already contains 50 or more owners
656	     */
657	    private void requireCityHasCapacity(String city) {
658	        long cityOwners = this.clinicService.findAllOwners().stream()
659	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
660	            .count();
661	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
662	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
663	        }
664	    }
665	
666	    /**
667	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
668	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
669	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
670	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
671	     * such owners never match one another as a household.
672	     *
673	     * @param owner the newly mapped owner about to be saved
674	     */
675	    private void assignHouseholdId(Owner owner) {
676	        String postcode = owner.getPostcode();
677	        if (postcode == null || postcode.isBlank()) {
678	            owner.setHouseholdId(null);
679	            return;
680	        }
681	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
682	    }
683	
684	    /**
685	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
686	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
687	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
688	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
689	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
690	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
691	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
692	     *
693	     * @param owner the owner whose capped membership level should be computed
694	     * @return the membership level, capped at one above the existing household maximum
695	     */
696	    private int cappedMembershipLevel(Owner owner) {
697	        populateHouseholdMemberCount(owner);
698	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
699	        Integer cap = householdMembershipLevelCap(owner);
700	        return cap == null ? level : Math.min(level, cap);
701	    }
702	
703	    /**
704	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
705	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
706	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
707	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
708	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
709	     * member has no cap.
710	     *
711	     * @param owner the owner whose household level cap should be computed
712	     * @return one above the existing household maximum level, or {@code null} when no cap applies
713	     */
714	    private Integer householdMembershipLevelCap(Owner owner) {
715	        String householdId = owner.getHouseholdId();
716	        Integer id = owner.getId();
717	        if (householdId == null || id == null) {
718	            return null;
719	        }
720	        Integer maxLevel = null;
721	        for (Owner member : this.clinicService.findAllOwners()) {
722	            Integer memberId = member.getId();
723	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
724	                int memberLevel = cappedMembershipLevel(member);
725	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
726	            }
727	        }
728	        return maxLevel == null ? null : maxLevel + 1;
729	    }
730	
731	    /**
732	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
733	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
734	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
735	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
736	     * already been saved it is itself among the members returned.
737	     *
738	     * @param owner the owner whose household members should be resolved
739	     * @return the members of the owner's household, never empty
740	     */
741	    private List<Owner> householdMembers(Owner owner) {
742	        String householdId = owner.getHouseholdId();
743	        if (householdId == null) {
744	            return List.of(owner);
745	        }
746	        return this.clinicService.findAllOwners().stream()
747	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
748	            .toList();
749	    }
750	
751	    /**
752	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
753	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
754	     * owner itself). An owner with no household is counted as a household of one.
755	     *
756	     * @param owner the owner whose household size should be resolved
757	     */
758	    private void populateHouseholdMemberCount(Owner owner) {
759	        owner.setHouseholdMemberCount(householdMembers(owner).size());
760	    }
761	
762	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
763	    @Override
764	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
765	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
766	        if (currentOwner == null) {
767	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
768	        }
769	        validatePostcode(ownerFieldsDto);
770	        currentOwner.setAddress(ownerFieldsDto.getAddress());
771	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
772	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
773	        currentOwner.setCity(ownerFieldsDto.getCity());
774	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
775	        currentOwner.setLastName(ownerFieldsDto.getLastName());
776	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
777	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
778	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
779	        this.clinicService.saveOwner(currentOwner);
780	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
781	    }
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Transactional
785	    @Override
786	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
787	        Owner owner = this.clinicService.findOwnerById(ownerId);
788	        if (owner == null) {
789	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
790	        }
791	        owner.setDeleted(true);
792	        this.clinicService.saveOwner(owner);
793	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
794	    }
795	
796	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
797	    @Override
798	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
799	        Owner owner = this.clinicService.findOwnerById(ownerId);
800	        if (owner == null) {
801	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
802	        }
803	        HttpHeaders headers = new HttpHeaders();
804	        Pet pet = petMapper.toPet(petFieldsDto);
805	        owner.setId(ownerId);
806	        pet.setOwner(owner);
807	        pet.getType().setName(null);
808	        this.clinicService.savePet(pet);
809	        PetDto petDto = petMapper.toPetDto(pet);
810	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
811	            .buildAndExpand(pet.getId()).toUri());
812	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
813	    }
814	
815	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
816	    @Override
817	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
818	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
819	        if (currentOwner != null) {
820	            Pet currentPet = this.clinicService.findPetById(petId);
821	            if (currentPet != null) {
822	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
823	                currentPet.setName(petFieldsDto.getName());
824	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
825	                this.clinicService.savePet(currentPet);
826	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
827	            }
828	        }
829	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
830	    }
831	
832	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
833	    @Override
834	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
835	        HttpHeaders headers = new HttpHeaders();
836	        Visit visit = visitMapper.toVisit(visitFieldsDto);
837	        Pet pet = new Pet();
838	        pet.setId(petId);
839	        visit.setPet(pet);
840	        this.clinicService.saveVisit(visit);
841	        VisitDto visitDto = visitMapper.toVisitDto(visit);
842	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
843	            .buildAndExpand(visit.getId()).toUri());
844	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
845	    }
846	
847	
848	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
849	    @Override
850	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
851	        Owner owner = this.clinicService.findOwnerById(ownerId);
852	        if (owner != null) {
853	            Pet pet = owner.getPet(petId);
854	            if (pet != null) {
855	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
856	            }
857	        }
858	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
859	    }
860	}
